import{_ as t,o,c as d,a3 as a}from"./chunks/framework.B9qR_F1m.js";const f=JSON.parse('{"title":"Command reference","description":"","frontmatter":{},"headers":[],"relativePath":"commands.md","filePath":"commands.md"}'),r={name:"commands.md"};function s(c,e,i,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="command-reference" tabindex="-1">Command reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command reference&quot;">​</a></h1><p>Every ripeat command, what it changes, and its options. <code>ripeat</code> with no arguments prints the list. Commands that change your machine <strong>show what they will do and ask first</strong>; <code>--yes</code> (or <code>-y</code>) answers for you, and is required when there is no terminal to ask in.</p><h2 id="look-first-these-change-nothing" tabindex="-1">Look first: these change nothing <a class="header-anchor" href="#look-first-these-change-nothing" aria-label="Permalink to &quot;Look first: these change nothing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>ripeat plan [tool[@version] ...]</code></td><td>The same as <code>install --dry-run</code>: what would happen, in order, and why. Takes <code>--file</code>, <code>--profile</code>, <code>--scope</code>, <code>--no-lock</code></td></tr><tr><td><code>ripeat assess [tool[@version] ...]</code></td><td>How risky the plan is, with reasons (<a href="./assess">Risk and <code>assess</code></a>). <code>--json</code> for programs, <code>--fail-on medium|high</code> to exit with an error at that level, <code>--accounts &lt;file&gt;</code> to rate a user policy too, <code>--file</code>, <code>--profile</code>, <code>--scope</code>, <code>--no-lock</code></td></tr><tr><td><code>ripeat find &lt;name&gt;</code></td><td>Where a tool could be installed from: package managers and GitHub (<a href="./find-and-add">Install by name</a>). <code>--no-github</code> skips GitHub</td></tr><tr><td><code>ripeat list</code></td><td>The tools ripeat manages, their versions, and whether they were already there</td></tr><tr><td><code>ripeat history</code></td><td>The last 20 runs and how each ended</td></tr><tr><td><code>ripeat outdated</code></td><td>Tools with a newer version available (<a href="./upgrades">Versions and upgrades</a>)</td></tr><tr><td><code>ripeat recipes</code></td><td>The tools ripeat knows how to install</td></tr><tr><td><code>ripeat recipes check [name ...]</code></td><td>Asks the real sources whether each recipe still works on this machine (<a href="./recipes">Recipes</a>)</td></tr><tr><td><code>ripeat rules</code></td><td>The administrator policy in force here, if any (<a href="./admin-policy">Administrator policy</a>)</td></tr><tr><td><code>ripeat validate [file ...]</code></td><td>Checks profiles, recipes, policies and lockfiles for mistakes (<a href="./validate">Checking your files</a>)</td></tr><tr><td><code>ripeat schema recipe|profile|policy|admin-policy</code></td><td>A JSON Schema for editor completion</td></tr><tr><td><code>ripeat version [--check]</code></td><td>The version. <code>--check</code> asks GitHub whether a newer release is out and how to upgrade</td></tr></tbody></table><h2 id="change-the-machine-these-ask-first" tabindex="-1">Change the machine: these ask first <a class="header-anchor" href="#change-the-machine-these-ask-first" aria-label="Permalink to &quot;Change the machine: these ask first&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>ripeat install [tool[@version] ...]</code></td><td>Shows the plan and its risk, asks, then installs (<a href="./install-and-rollback">Install, uninstall, rollback</a>). With no names it reads <code>./ripeat.yaml</code>. A name with no recipe, at a keyboard, is looked up and offered to you to add</td></tr><tr><td></td><td><code>--file &lt;path&gt;</code> use that profile · <code>--profile &lt;name&gt;</code> use a saved profile (repeatable) · <code>--dry-run</code> only show · <code>--scope user|system</code> only methods that do not / do need admin rights · <code>--no-lock</code> ignore <code>ripeat.lock</code> · <code>--no-rollback</code> keep a failed run&#39;s partial changes · <code>--accept-risk</code> run a HIGH-risk plan without asking · <code>--yes</code> answer the question</td></tr><tr><td><code>ripeat uninstall &lt;tool&gt; ...</code></td><td>Removes tools ripeat installed. Refuses a tool that another managed tool still needs unless <code>--force</code>. <code>--dry-run</code>, <code>--yes</code></td></tr><tr><td><code>ripeat upgrade [tool ...]</code></td><td>Upgrades the outdated tools. Cannot be rolled back. <code>--dry-run</code>, <code>--yes</code></td></tr><tr><td><code>ripeat rollback</code></td><td>Undoes the most recent run that is not already undone; run it again for the one before (<a href="./install-and-rollback">Install, uninstall, rollback</a>). <code>--dry-run</code>, <code>--yes</code></td></tr><tr><td><code>ripeat resume</code></td><td>Carries on an install that paused for a restart (<a href="./reboots">Restarts and <code>resume</code></a>). <code>--force</code>, <code>--dry-run</code>, <code>--accept-risk</code></td></tr><tr><td><code>ripeat lock [tool ...]</code></td><td>Writes <code>ripeat.lock</code> with the exact versions installed (<a href="./lockfile">The lockfile</a>)</td></tr><tr><td><code>ripeat policy</code></td><td>Users, groups and admin rights from <code>ripeat.policy.yaml</code> (<a href="./policy">Users and groups</a>). A dry run unless <code>--apply</code>; <code>--allow-admin</code> is needed if the file grants admin rights; <code>--file &lt;path&gt;</code></td></tr></tbody></table><h2 id="recipes-profiles-and-sharing" tabindex="-1">Recipes, profiles and sharing <a class="header-anchor" href="#recipes-profiles-and-sharing" aria-label="Permalink to &quot;Recipes, profiles and sharing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>ripeat add &lt;name|owner/repo&gt;</code></td><td>Looks a tool up, drafts a recipe, shows it, and saves it if you agree (<a href="./find-and-add">Install by name</a>). <code>--from &lt;method&gt;|github</code> pick the source · <code>--as &lt;name&gt;</code> recipe name · <code>--bin &lt;program&gt;</code> the program to put on PATH · <code>--no-github</code> · <code>--refresh</code> draft one you added again and show the difference · <code>--manual --check &lt;cmd&gt; --note &lt;text&gt;</code> record a tool you install by hand (<a href="./recipes">Recipes</a>) · <code>--yes</code></td></tr><tr><td><code>ripeat add &lt;name&gt; --url &lt;https address&gt; --sha256 &lt;hex&gt;</code></td><td>Drafts a recipe for a vendor <code>.dmg</code>, <code>.pkg</code>, <code>.msi</code> or <code>.exe</code>, after checking the checksum and the vendor&#39;s signature (<a href="./installers">Vendor installers</a>). <code>--kind</code>, <code>--app</code>, <code>--signer</code>, <code>--product</code>, <code>--args</code>, <code>--uninstall-args</code>, <code>--unsigned</code></td></tr><tr><td><code>ripeat bundle</code></td><td><code>export &lt;profile&gt; [file] [--force]</code>, <code>import &lt;file-or-https-url&gt; [name] [--sha256 &lt;hex&gt;] [--allow-shell] [--force]</code>: share a profile together with the recipes you added (<a href="./bundles">Bundles: profile + recipes</a>). Importing shows and rates every recipe and asks you; there is no <code>--yes</code></td></tr><tr><td><code>ripeat profile</code></td><td><code>save &lt;name&gt; [file]</code>, <code>list</code>, <code>show &lt;name&gt;</code>, <code>export &lt;name&gt; [file]</code>, <code>import &lt;file-or-https-url&gt; [name]</code>, <code>remove &lt;name&gt;</code> (<a href="./profiles">Profiles: your list</a>)</td></tr><tr><td><code>ripeat tap</code></td><td>Recipe packs from GitHub or an https address: <code>list</code>, <code>show &lt;name&gt;</code>, <code>add owner/repo</code> or <code>add https://...</code> (<code>--ref</code>, <code>--sha256</code>, <code>--as</code>, <code>--allow-shell</code>), <code>update [name]</code>, <code>remove &lt;name&gt;</code> (<a href="./taps">Recipe packs (taps)</a>). Adding and updating ask you; there is no <code>--yes</code></td></tr><tr><td><code>ripeat drafts</code></td><td>Recipes an AI assistant prepared: <code>list</code>, <code>show &lt;name&gt;</code>, <code>approve &lt;name&gt;</code>, <code>reject &lt;name&gt;</code> (<a href="./drafts">Drafts from an assistant</a>). Approving asks you; there is no <code>--yes</code></td></tr></tbody></table><h2 id="ai-assistants" tabindex="-1">AI assistants <a class="header-anchor" href="#ai-assistants" aria-label="Permalink to &quot;AI assistants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>ripeat mcp</code></td><td>Runs ripeat as an MCP server over standard input and output, so an assistant can look things up, plan, rate risk and prepare drafts (<a href="./mcp">ripeat as an MCP server</a>). It is started by the assistant, not by you</td></tr><tr><td><code>ripeat mcp setup [--client claude-code|claude-desktop|codex] [--allow-run] [--print] [--yes]</code></td><td>Connects ripeat to an AI assistant: shows exactly what it will change, keeps a backup of any file it edits, and asks first (<a href="./mcp">ripeat as an MCP server</a>)</td></tr><tr><td><code>ripeat mcp --allow-run</code></td><td>Also offers two tools that install or undo, but only after you confirm each run in your own app</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>RIPEAT_HOME</code></td><td>Where ripeat keeps its state, recipes, profiles, drafts and packs. Default: a <code>ripeat</code> folder in your user config folder (<a href="./getting-started">Getting started</a>)</td></tr><tr><td><code>GITHUB_TOKEN</code></td><td>Optional. Raises GitHub&#39;s rate limits for <code>find</code>, <code>add</code> and <code>tap</code>, and lets <code>tap</code> read a private repository you can access</td></tr><tr><td><code>NO_COLOR</code></td><td>Set it to turn off the colours ripeat uses on a terminal</td></tr></tbody></table><h2 id="exit-status" tabindex="-1">Exit status <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status&quot;">​</a></h2><p><code>0</code> on success. Anything else means the command failed or was refused (a declined question, a blocked tool, a policy). The message says why, and a command that stopped before changing anything says so.</p>',14)])])}const m=t(r,[["render",s]]);export{f as __pageData,m as default};
